// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    // fuzzed params: caller address and a timestamp to warp to
    function testFuzz_property(address caller, uint256 ts) public {
        // keep caller non-zero and ts in a reasonable range
        vm.assume(caller != address(0));
        // bound timestamp to avoid extremely large values
        ts = bound(ts, 1, type(uint64).max);

        // fund caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // move to chosen timestamp and perform first valid payable fallback call
        vm.warp(ts);
        vm.prank(caller);
        // call fallback by using a low-level call (fuzzed address is EOA so call succeeds to fallback)
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call must succeed");

        // Immediately attempt a second identical call at the same timestamp
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // The GENERAL RULE: after the first successful payable fallback of 10 ether,
        // c.pastBlockTime is updated to block.timestamp, so a second call in the same timestamp must revert (ok2==false).
        // The buggy mutant that removed the assignment may allow ok2==true for some inputs; assert the property that ok2 is false.
        assertTrue(!ok2);
    }
}
